{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Viqualine, a basic piperidine-quinoline with an aromatic nitrogen heterocycle, showed absolute oral bioavailability of 80% in healthy subjects, supporting high F for the similarly basic heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Bicifadine, an azabicyclic amine with an aryl substituent, had approximately 67% absolute oral bioavailability in humans, supporting high F for the query's fused basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cibenzoline, a basic heteroaromatic drug, showed absolute oral bioavailability of 0.86 versus IV in healthy volunteers, consistent with high oral F for a small basic heterocyclic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, a small heterocyclic amine-containing drug, had absolute oral bioavailability of 73 ± 25% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Alvimopan, a piperidine phenol, had low absolute oral bioavailability of about 6% in humans; this contradictory example is less transferable because the query lacks the polar phenolic/acidic features driving alvimopan's poor absorption.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Fenoldopam showed poor oral bioavailability in humans, but its catechol and chlorine substituents create conjugation/polarity liabilities not present in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, weakly basic fused heteroaromatic amine. Most transferable experimental analogues with similar piperidine/heteroaromatic cores show high absolute oral bioavailability (67–90%), while the low-bioavailability examples contain polar phenolic/catechol or acidic features absent from the query. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the exact query molecule.",
    "Morgan similarity scores to all evidence molecules are low, so structural transfer is based on shared pharmacophore features rather than close analogues.",
    "The query's specific fused polycyclic heteroaromatic system is not represented by a close experimental analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

